// Physician Assistant – Medical Case Challenge Practice Test 1. Original case-based questions written for
// Valus from the HOSA 2026–27 test plan, slightly harder than the sample items: choosing tests,
// interpreting findings and naming the most likely diagnosis.
import {q, mix} from './q.js';
const CMDT='Papadakis et al., Current Medical Diagnosis & Treatment', MP='MedlinePlus';
const DP='Disease Process & Terminology (includes cancer & neoplasms)', INTEG='Integumentary', MSK='Musculoskeletal', CIRC='Circulatory & Lymphatic', RESP='Respiratory', DIG='Digestive', ENDO='Endocrine', NERV='Nervous & Senses', REPRO='Reproductive', URIN='Urinary', MENT='Mental Disorders', ASSESS='Patient Assessment', DX='Diagnosis';

export default {
 id:'physician-assistant-1',
 event:'Physician Assistant - Medical Case Challenge',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Current Medical Diagnosis & Treatment (CMDT) and MedlinePlus',
 plan:[{area:DP,weight:10},{area:INTEG,weight:4},{area:MSK,weight:6},{area:CIRC,weight:10},{area:RESP,weight:6},{area:DIG,weight:10},{area:ENDO,weight:6},{area:NERV,weight:8},{area:REPRO,weight:4},{area:URIN,weight:4},{area:MENT,weight:6},{area:ASSESS,weight:12},{area:DX,weight:14}],
 questions:mix([
  q(DP,'Which blood test is used as a tumor marker for prostate cancer?','PSA',['CEA','AFP','CA-125'],'B','Prostate-specific antigen rises with prostate cancer but also with benign enlargement and inflammation, so it is not diagnostic alone.',CMDT),
  q(DP,'What happens in an autoimmune disease?','The immune system attacks the body',['The immune system is absent','Bacteria cause chronic infection','Cells divide without control'],'D','Examples include type 1 diabetes, rheumatoid arthritis and lupus.',MP),
  q(DP,'How is sepsis defined?','Organ dysfunction from the response to infection',['Any infection that causes a fever','Bacteria found on the skin','A localized skin abscess'],'A','Sepsis is an emergency. Early antibiotics, fluids and source control improve survival.',CMDT),
  q(DP,'A cancer that arises from epithelial cells, such as those lining the lung or colon, is called a:','Carcinoma',['Sarcoma','Lymphoma','Leukemia'],'C','Carcinomas are the most common cancers. Sarcomas arise from connective tissue, lymphomas from lymphocytes and leukemias from blood-forming cells.',CMDT),
  q(DP,'What is a prognosis?','The predicted outcome',['The cause of a disease','The treatment plan','The patient’s symptoms'],'B','Prognosis estimates how a condition will progress and the likelihood of recovery. Etiology is the cause.',MP),
  q(INTEG,'A 65-year-old has a pearly, raised lesion with tiny blood vessels on the nose that has slowly grown. What is most likely?','Basal cell carcinoma',['Melanoma','Psoriasis','Seborrheic keratosis'],'D','Basal cell carcinoma is the most common skin cancer. It grows slowly and rarely metastasizes but can damage local tissue.',CMDT),
  q(INTEG,'A patient has a warm, red, tender, spreading area on the lower leg with fever. What is the most likely diagnosis?','Cellulitis',['Contact dermatitis','Venous stasis without infection','Psoriasis'],'A','Cellulitis is a bacterial infection of the deeper skin, usually from streptococci or staphylococci, treated with antibiotics.',CMDT),
  q(MSK,'A patient has a hot, swollen knee with fever. What is the most important next step to rule out septic arthritis?','Joint aspiration and fluid analysis',['An X-ray only','A blood glucose test','Physical therapy referral'],'C','Analyzing synovial fluid (cell count, Gram stain, culture, crystals) distinguishes infection from gout. Septic arthritis can destroy a joint quickly.',CMDT),
  q(MSK,'Which antibody test is most specific for rheumatoid arthritis?','Anti-CCP antibodies',['Antinuclear antibodies (ANA)','Rheumatoid factor alone','HLA-B27'],'B','Anti-cyclic citrullinated peptide antibodies are highly specific for RA. Rheumatoid factor is less specific, and ANA is common in lupus.',CMDT),
  q(MSK,'On a DEXA scan, which T-score indicates osteoporosis?','−2.5 or lower',['+1.0 or higher','Between −1.0 and +1.0','Between −1.0 and −2.5'],'D','A T-score of −1.0 or above is normal, between −1.0 and −2.5 is osteopenia, and −2.5 or below is osteoporosis.',CMDT),
  q(CIRC,'A patient with crushing chest pain has ST-segment elevation in leads II, III and aVF. What does this indicate?','An acute inferior STEMI',['Normal ECG findings','Stable angina','Pericarditis in every case'],'A','ST elevation in contiguous inferior leads suggests occlusion of the vessel supplying the inferior wall, often the right coronary artery. Rapid reperfusion is needed.',CMDT),
  q(CIRC,'A patient has a swollen, painful calf after a long flight. Which test is used to confirm a deep vein thrombosis?','Leg compression ultrasound',['Chest X-ray','An echocardiogram','Electromyography'],'C','A negative D-dimer can help rule out DVT when pretest probability is low, but ultrasound confirms it.',CMDT),
  q(CIRC,'An ECG shows an irregularly irregular rhythm with no distinct P waves. What is the main long-term risk of this rhythm?','Stroke from atrial clots',['Episodes of low blood sugar','Kidney stones','Recurrent pneumonia'],'B','In atrial fibrillation, blood pools in the atria and can clot. Anticoagulation is considered based on stroke risk scores.',CMDT),
  q(CIRC,'Under the 2017 ACC/AHA guideline, which blood pressure is classified as stage 2 hypertension?','142/92 mm Hg',['118/76 mm Hg','124/78 mm Hg','132/84 mm Hg'],'D','Normal is below 120/80, elevated is 120–129/<80, stage 1 is 130–139 or 80–89, and stage 2 is 140/90 or higher.',CMDT),
  q(CIRC,'A patient has fatigue, a microcytic anemia and a low ferritin. What is the most likely cause?','Iron deficiency',['Vitamin B12 deficiency','Folate deficiency','Hemolysis from a transfusion reaction'],'A','Low ferritin is the most specific sign of iron deficiency. In adults, a source of blood loss, such as GI bleeding, should be sought.',CMDT),
  q(RESP,'A patient has fever, productive cough and crackles over the right lower lobe. What would a chest X-ray most likely show?','Right lower lobe consolidation',['A completely normal film','Hyperinflated lungs only','A collapsed left lung'],'C','Lobar consolidation is typical of bacterial pneumonia, where alveoli fill with fluid and inflammatory cells.',CMDT),
  q(RESP,'Which imaging test is most commonly used to diagnose a pulmonary embolism?','CT pulmonary angiography',['Plain chest X-ray','Abdominal ultrasound','MRI of the brain'],'B','CT pulmonary angiography shows clots in the pulmonary arteries. A V/Q scan may be used when contrast is unsafe.',CMDT),
  q(RESP,'Which spirometry finding supports a diagnosis of asthma?','Obstruction that reverses with albuterol',['Normal results that never change','Reduced total lung capacity','Improvement only after antibiotics'],'D','Significant improvement in FEV1 after albuterol shows reversible obstruction, typical of asthma.',CMDT),
  q(DIG,'A patient with right upper quadrant pain stops inhaling when the examiner presses under the right ribs. What does this suggest?','Acute cholecystitis',['Appendicitis','Diverticulitis','Pancreatitis'],'A','This is a positive Murphy sign. Ultrasound is the first imaging test for suspected gallbladder disease.',CMDT),
  q(DIG,'What are the two most common causes of acute pancreatitis in adults?','Gallstones and alcohol',['Smoking and caffeine','Viral infection and stress','Lactose intolerance and spicy food'],'C','Gallstones blocking the pancreatic duct and heavy alcohol use cause most cases. Lipase above three times normal supports the diagnosis.',CMDT),
  q(DIG,'Which blood test is commonly used to screen for celiac disease?','tTG-IgA antibody',['A hemoglobin A1c level','Lipid panel','Serum amylase'],'B','A positive tTG-IgA is usually confirmed with small-bowel biopsy while the patient is still eating gluten.',CMDT),
  q(DIG,'A patient’s hepatitis B surface antigen (HBsAg) is positive. What does this indicate?','Current hepatitis B infection',['Immunity from vaccination only','Past infection that has fully cleared','Hepatitis C infection'],'D','HBsAg means the virus is present. Vaccinated people have anti-HBs (surface antibody) without HBsAg.',CMDT),
  q(DIG,'A patient vomits blood and has black, tarry stools. Where is the bleeding most likely coming from?','The upper GI tract',['The rectum','The sigmoid colon','The anus'],'A','Blood digested as it passes through the gut turns stool black. Upper endoscopy is the key diagnostic and treatment step.',CMDT),
  q(ENDO,'Which hemoglobin A1c result meets the diagnostic criterion for diabetes?','6.5% or higher',['5.0% or higher','5.6% or higher','6.0% or higher'],'C','An A1c of 6.5% or higher (confirmed) indicates diabetes; 5.7–6.4% indicates prediabetes.',CMDT),
  q(ENDO,'Which lab pattern fits primary hypothyroidism?','High TSH and low free T4',['Low TSH and high free T4','Normal TSH and high free T4','Low TSH and low free T4'],'B','A failing thyroid makes too little hormone, so the pituitary releases more TSH. Hashimoto’s thyroiditis is the most common cause.',CMDT),
  q(ENDO,'A patient on long-term prednisone develops a round face, upper-back fat pad and purple stretch marks. What is this?','Cushing syndrome',['Addison disease','Graves disease','Diabetes insipidus'],'D','Excess glucocorticoid, most often from medication, causes Cushing syndrome. Addison disease is cortisol deficiency.',CMDT),
  q(NERV,'A patient arrives with sudden one-sided weakness. What is the first imaging test, and why?','A noncontrast head CT',['An MRI of the spine','A chest X-ray','An EEG to look for seizures'],'A','Hemorrhage must be excluded before giving clot-dissolving therapy. CT is fast and widely available.',CMDT),
  q(NERV,'Before her headaches, a patient sees zigzag lines for about 20 minutes. The headache is throbbing and one-sided with nausea. What is most likely?','Migraine with aura',['Tension headache','Cluster headache','Subarachnoid hemorrhage'],'C','Visual auras usually last 5–60 minutes before the headache. A sudden “worst headache of my life” suggests a subarachnoid hemorrhage instead.',CMDT),
  q(NERV,'A patient cannot close one eye or wrinkle the forehead on the same side, and the mouth droops. Why does this suggest Bell’s palsy rather than a stroke?','Forehead weakness points to a peripheral nerve',['Stroke always affects both sides of the face','Bell’s palsy never affects the mouth','Stroke always causes eye closure weakness'],'B','A central lesion such as a stroke usually spares the forehead because it receives input from both sides of the brain.',CMDT),
  q(NERV,'A college student has fever, severe headache, neck stiffness and confusion. Which test confirms the diagnosis?','Lumbar puncture',['A throat culture','Urinalysis','Electrocardiogram'],'D','Bacterial meningitis is an emergency; antibiotics are often started immediately, sometimes before the lumbar puncture.',CMDT),
  q(REPRO,'A woman with a positive pregnancy test has one-sided pelvic pain and spotting. Ultrasound shows no pregnancy in the uterus. What must be ruled out?','Ectopic pregnancy',['Normal early pregnancy','Urinary tract infection','Menopause'],'A','An ectopic pregnancy, usually in a fallopian tube, can rupture and cause life-threatening bleeding.',CMDT),
  q(REPRO,'A 14-year-old has sudden, severe testicular pain, a high-riding testis and an absent cremasteric reflex. What is the priority?','Emergency surgery for testicular torsion',['Antibiotics for epididymitis','Ice and rest for a week','Routine follow-up in one month'],'C','Torsion twists the spermatic cord and cuts off blood flow. The testis can often be saved if treated within about 6 hours.',CMDT),
  q(URIN,'A patient has severe, colicky flank pain spreading to the groin, with blood in the urine. What is the likely diagnosis?','Kidney stone',['Appendicitis','Bladder cancer','Prostatitis'],'B','Noncontrast CT is the preferred test. Most small stones pass with pain control and fluids.',CMDT),
  q(URIN,'A patient with a urinary tract infection develops fever, flank pain and tenderness at the costovertebral angle. What does this suggest?','Pyelonephritis',['Simple cystitis','Urethritis','Kidney stone without infection'],'D','Infection has spread to the kidney. White blood cell casts in the urine support the diagnosis.',CMDT),
  q(MENT,'Which questionnaire is commonly used in primary care to screen for and track depression?','PHQ-9',['CAGE','Glasgow Coma Scale','Mini-Cog'],'A','The PHQ-9 scores the nine DSM criteria for major depression and includes a question about thoughts of self-harm.',CMDT),
  q(MENT,'How long must signs of the disorder last for a diagnosis of schizophrenia?','At least 6 months',['At least 1 week','At least 1 month only','At least 5 years'],'C','Schizophrenia requires continuous signs for 6 months, including at least 1 month of active symptoms. Shorter durations suggest other diagnoses.',CMDT),
  q(MENT,'A hospitalized patient who drinks heavily develops tremor, sweating and agitation about a day after admission. Which tool guides treatment?','The CIWA-Ar scale',['The PHQ-9 depression scale','The Apgar score','The Braden scale'],'B','CIWA-Ar scores withdrawal severity to guide benzodiazepine dosing. Severe withdrawal can lead to seizures and delirium tremens.',CMDT),
  q(ASSESS,'What does the mnemonic OLDCARTS help a clinician gather?','The history of present illness',['The family history','The physical exam findings','The medication list'],'D','Onset, Location, Duration, Character, Aggravating/relieving factors, Radiation, Timing and Severity describe a symptom in detail.',CMDT),
  q(ASSESS,'What is the review of systems?','Symptom questions by body system',['The physical exam of each organ','A list of the patient’s lab results','The final diagnosis and plan'],'A','The review of systems uncovers symptoms the patient may not mention, organized by body system.',CMDT),
  q(ASSESS,'In the abdominal exam, why is auscultation done before palpation?','Palpation can change bowel sounds',['Auscultation is the most important step','Palpation is painful only after listening','Bowel sounds disappear after inspection'],'C','The order for the abdomen is inspection, auscultation, percussion, then palpation, so touching does not alter what is heard.',CMDT),
  q(ASSESS,'In an adult, stroking the sole of the foot causes the big toe to extend upward and the toes to fan. What does this suggest?','An upper motor neuron lesion',['A normal adult reflex','A peripheral nerve injury','A muscle strain'],'B','A positive Babinski sign is normal in infants but in adults suggests damage to the brain or spinal cord motor pathways.',CMDT),
  q(ASSESS,'A patient’s blood pressure is 150/90 mm Hg. What is the pulse pressure?','60 mm Hg',['90 mm Hg','150 mm Hg','240 mm Hg'],'D','Pulse pressure = systolic − diastolic = 150 − 90 = 60 mm Hg. A wide pulse pressure can occur with stiff arteries.',CMDT),
  q(ASSESS,'How should the chief complaint be recorded in the medical record?','In the patient’s own words',['As the clinician’s diagnosis','As a list of lab values','In medical abbreviations only'],'A','Recording the complaint in the patient’s words (for example, “my chest feels tight”) preserves their description.',CMDT),
  q(DX,'What is a differential diagnosis?','A list of possible explanations',['The single confirmed diagnosis','A diagnosis made by a specialist','The cost of diagnostic tests'],'B','Clinicians narrow the differential using history, exam and testing until the most likely diagnosis remains.',CMDT),
  q(DX,'A test with very high sensitivity is negative. What can the clinician conclude?','The disease can likely be ruled out',['The disease is definitely present','The test was performed incorrectly','The disease is confirmed'],'D','“SnNout”: a negative result on a highly sensitive test helps rule out disease. A positive result on a highly specific test helps rule it in.',CMDT),
  q(DX,'Why does the positive predictive value of a test fall when a disease is rare?','More positives are false positives',['Sensitivity increases','The test becomes more specific','Fewer people are tested'],'A','Positive predictive value depends on prevalence. Screening low-risk populations produces more false positives.',CMDT),
  q(DX,'A CBC shows a high white blood cell count with many neutrophils and band forms. What does this most suggest?','A bacterial infection',['A viral infection only','An allergic reaction','Iron deficiency'],'C','An increase in immature neutrophils (a “left shift”) is typical of bacterial infection or acute inflammation.',CMDT),
  q(DX,'A patient with shortness of breath has a markedly elevated B-type natriuretic peptide (BNP). What does this support?','Heart failure',['Asthma','Pneumonia only','Anxiety'],'B','The ventricles release BNP when stretched. A normal BNP makes heart failure unlikely as the cause of dyspnea.',CMDT),
  q(DX,'A teen has fever, swollen tender neck lymph nodes, tonsillar exudates and no cough. Which tool estimates the likelihood of strep throat?','The Centor criteria',['The CAGE questionnaire','The Glasgow Coma Scale','The Wells score for DVT'],'D','The Centor (or McIsaac) score uses these findings to decide whether to test or treat for group A strep.',CMDT),
  q(DX,'What is generally required to confirm a diagnosis of cancer?','A biopsy with tissue examination',['A single blood test','A patient questionnaire','A family history'],'A','Imaging and tumor markers raise suspicion, but a pathologist examining tissue provides the definitive diagnosis and type.',CMDT)
 ],157)
};
